// Two truthful exchanges share a visible middle value and one law.
// The retained middle source distinguishes their join from a lawful return.
public typealias SwapSeamFirst = ExchangeRoutingWithReserve<FourCourtA, FourCourtO, FourCourtB>
public typealias SwapSeamReturn = ExchangeRoutingWithReserve<FourCourtB, FourCourtO, FourCourtA>
public typealias SwapSeamOther = ExchangeRoutingWithReserve<FourCourtB, FourCourtO, FourCourtC>
public typealias SwapSeamFirstActual = LocalCourtSame<SwapSeamFirst.Answer, RoutingModule<FourCourtB, FourCourtO, FourCourtA>>
public typealias UseSwapSeamFirstActual = LocalCourtUse<SwapSeamFirstActual>
public typealias SwapSeamOtherActual = LocalCourtSame<SwapSeamOther.Answer, RoutingModule<FourCourtC, FourCourtO, FourCourtB>>
public typealias UseSwapSeamOtherActual = LocalCourtUse<SwapSeamOtherActual>
public typealias SwapSeamVisibleAgreement = LocalCourtSame<SwapSeamFirst.Answer.Left.Left, SwapSeamOther.Left.Left.Left>
public typealias UseSwapSeamVisibleAgreement = LocalCourtUse<SwapSeamVisibleAgreement>
public typealias SwapSeamSameLaw = LocalCourtSame<SwapSeamFirst.Predicate, SwapSeamOther.Predicate>
public typealias UseSwapSeamSameLaw = LocalCourtUse<SwapSeamSameLaw>
public typealias SwapSeamActualReturnSource = LocalCourtSame<SwapSeamFirst.Answer, SwapSeamReturn.Left>
public typealias UseSwapSeamActualReturnSource = LocalCourtUse<SwapSeamActualReturnSource>
public typealias SwapSeamActualReturn = LocalCourtSame<SwapSeamReturn.Answer, SwapSeamFirst.Left>
public typealias UseSwapSeamActualReturn = LocalCourtUse<SwapSeamActualReturn>
